cat > src/tokens.ts <<'EOF'
// Applies the repository's design tokens as CSS custom properties.
// resources/jusprin/ui/design-tokens.json is the implementation source of
// truth; the stylesheet must read var(--...) rather than hard-code a colour,
// radius, or spacing value. tokens.test.ts holds the stylesheet to that.

import tokens from '@resources/jusprin/ui/design-tokens.json';
import type { Appearance } from './bridge/protocol';

type TokenGroup = Record<string, string>;
type SemanticMode = Record<string, TokenGroup>;
type Scale = Record<string, number>;

// `--<group>-<name>` for every semantic colour of one appearance mode.
export function semanticProperties(appearance: Appearance): Record<string, string> {
  const semantic = (tokens as { semantic: Record<string, SemanticMode> }).semantic;
  const mode = semantic[appearance] ?? semantic.light;
  const properties: Record<string, string> = {};
  for (const [group, values] of Object.entries(mode)) {
    for (const [name, value] of Object.entries(values)) {
      if (typeof value === 'string') properties[`--${group}-${name}`] = value;
    }
  }
  return properties;
}

// `--space-<step>` for the spacing scale and `--radius-<name>` for the radius
// scale, in px. The token file is unit-less DIP; CSS px is the DIP of a
// web view, so the numbers carry over unchanged.
export function dimensionProperties(): Record<string, string> {
  const { space, radius } = (tokens as { dimension: { space: Scale; radius: Scale } }).dimension;
  const properties: Record<string, string> = {};
  for (const [step, value] of Object.entries(space)) properties[`--space-${step}`] = `${value}px`;
  for (const [name, value] of Object.entries(radius)) properties[`--radius-${name}`] = `${value}px`;
  return properties;
}

function setProperties(properties: Record<string, string>): void {
  const root = document.documentElement;
  for (const [name, value] of Object.entries(properties)) root.style.setProperty(name, value);
}

export function applyAppearance(appearance: Appearance): void {
  setProperties(semanticProperties(appearance));
  document.documentElement.dataset.appearance = appearance;
}

// Dimensions do not change with appearance, so they are applied once, before
// the first render, from main.tsx. Nothing is in the document before that
// call, so no element is ever laid out without them.
export function applyDimensions(): void {
  setProperties(dimensionProperties());
}
EOF
