// Contract between design-tokens.json, tokens.ts, and styles.css: every
// dimension the stylesheet reads is one the token file defines, and no radius
// or on-scale spacing is written as a literal that a token change would leave
// behind.

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import tokens from '@resources/jusprin/ui/design-tokens.json';
import { applyAppearance, applyDimensions, dimensionProperties, semanticProperties } from './tokens';

const stylesheet = readFileSync(new URL('./styles.css', import.meta.url), 'utf8');

// Declarations of the spacing properties only: "padding: 8px 12px", "gap: 8px".
const spacingDeclarations = [...stylesheet.matchAll(/\b((?:padding|margin)(?:-(?:top|right|bottom|left))?|gap): *([^;{}]+)/g)]
  .map((m) => `${m[1]}: ${m[2].trim()}`);

describe('dimension tokens', () => {
  it('emits the spacing and radius scales in px, named by step and by role', () => {
    const properties = dimensionProperties();
    for (const [step, value] of Object.entries(tokens.dimension.space))
      expect(properties[`--space-${step}`]).toBe(`${value}px`);
    for (const [name, value] of Object.entries(tokens.dimension.radius))
      expect(properties[`--radius-${name}`]).toBe(`${value}px`);
    expect(properties['--radius-pill']).toBe('9999px');
  });

  it('lands on the document root alongside the colours', () => {
    applyDimensions();
    applyAppearance('dark');
    const style = document.documentElement.style;
    expect(style.getPropertyValue('--radius-standard')).toBe(`${tokens.dimension.radius.standard}px`);
    expect(style.getPropertyValue('--space-2')).toBe(`${tokens.dimension.space['2']}px`);
    expect(style.getPropertyValue('--surface-canvas')).toBe(tokens.semantic.dark.surface.canvas);
    expect(document.documentElement.dataset.appearance).toBe('dark');
  });
});

describe('styles.css', () => {
  it('reads only custom properties that tokens.ts emits', () => {
    const emitted = new Set([...Object.keys(semanticProperties('light')), ...Object.keys(dimensionProperties())]);
    const referenced = new Set([...stylesheet.matchAll(/var\((--[A-Za-z0-9-]+)/g)].map((m) => m[1]));
    expect([...referenced].filter((name) => !emitted.has(name))).toEqual([]);
  });

  it('writes no radius as a literal', () => {
    expect(stylesheet.match(/border-radius: *[0-9.]+px/g)).toBeNull();
  });

  it('writes no on-scale spacing as a literal', () => {
    const scale = new Set(Object.values(tokens.dimension.space).map((v) => `${v}px`));
    const offenders = spacingDeclarations.filter((declaration) =>
      declaration.split(/\s+/).some((value) => scale.has(value)));
    expect(offenders).toEqual([]);
  });
});
